head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF30612.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
};
scwin.fn_Search = function() {
    //var vMARKET_FLAG = getObjectValue(rdo_MARKET_FLAG);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    //var vATTR_TP_CD = getObjectValue(cmb_ATTR_TP_CD);
    var url = "/ListedCompany.do?method=listChargeIssue";
    url += "&MARKET_FLAG=1";
    url += "&DEP_CD=" + vDEP_CD;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&ATTR_TP_CD=";
    url += "&LIST_STATUS=Y";
    url += "&SECU_GRP_ID=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CURR.DataID = url;
    dts_CURR.Reset();
    $c.cm.ShowWin(grd_CURR);
};
scwin.fn_SearchHistory = function() {
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vISUR_CD = scwin.gIsurCd = dts_CURR.getCellData(dts_CURR.getRowPosition(), "ISUR_CD");
    var url = "/ListedCompany.do?method=listChargeHistory";
    url += "&MARKET_FLAG=1";
    url += "&DEP_CD=" + vDEP_CD;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&ATTR_TP_CD=";
    url += "&LIST_STATUS=Y";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_HIST.DataID = url;
    dts_HIST.Reset();
};
scwin.fn_read = function(row, colid) {
    if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_CURR.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "VIEW_DETAIL") {
        scwin.fn_SearchHistory();
    }
};
scwin.btn_HistExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_HIST, "유가_기업담당자현황", "", "2");
};
scwin.btn_CurrExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_CURR, "유가_기업담당자변경내역", "", "2");
};
scwin.btn_Tab1_Search_Isur_Cd_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.grd_CURR_OnClick = function(row, colid) {
    scwin.fn_read(row, colid);
};
scwin.dts_CURR_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_CURR);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_CurrExcel);
};
scwin.dts_HIST_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_HistExcel);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
